css:
body :where([data-bz-node="hc"]) .bz-block{padding:0}
body :where([data-bz-node="hc"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="hc"]>.bz-container{padding-inline:0}

body [data-bz-node="hc"]{background:#fff;padding:96px 0}
body [data-bz-node="hc"]>.bz-container{max-width:var(--container)}
body [data-bz-node="hc-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="hc-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="hc-intro"] .bz-text{max-width:640px;margin-top:20px}
body [data-bz-node="hc-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="hc-grid"]{display:grid;grid-template-columns:7fr 5fr;gap:24px;margin-top:40px;align-items:stretch}
body [data-bz-node="hc-grid"]>.bz-col{grid-column:auto}

/* hours card */
body [data-bz-node="hc-card"]{background:#fff;border:1px solid #e4e4e2;padding:34px 40px 22px;box-sizing:border-box}
body [data-bz-node="hc-ct"] h3{display:flex;align-items:center;gap:12px;font:700 15px/1.2 var(--font-heading);letter-spacing:.04em;text-transform:uppercase;color:var(--ink);margin:0 0 14px}
body [data-bz-node="hc-ct"] h3::before{content:"";width:20px;height:20px;background:var(--accent);-webkit-mask:url(/icons/clock.svg) center/20px no-repeat;mask:url(/icons/clock.svg) center/20px no-repeat}
body [data-bz-node="hc-days"]{display:block}
body [data-bz-node^="hc-day-"]{display:flex;align-items:baseline;gap:20px;padding:15px 0;border-bottom:1px solid #ececea}
body [data-bz-node^="hc-day-"]:last-child{border-bottom:0}
body [data-bz-node^="hc-dayname-"]{flex:0 0 150px}
body [data-bz-node^="hc-dayname-"] p{font:700 11.5px/1.4 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node^="hc-dayhours-"]{flex:1 1 auto}
body [data-bz-node^="hc-dayhours-"] p{font:400 14px/1.4 var(--font-body);color:#444;margin:0}

/* call card */
body [data-bz-node="hc-dark"]{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;background:#2a2723;padding:40px;box-sizing:border-box}
body [data-bz-node="hc-dicon"] figure{margin:0}
body [data-bz-node="hc-dicon"] img{width:26px;height:26px}
body [data-bz-node="hc-dicon"]{width:60px;height:60px;border-radius:50%;background:var(--accent);display:flex;align-items:center;justify-content:center}
body [data-bz-node="hc-dicon"] .bz-container,body [data-bz-node="hc-dicon"] figure{display:contents}
body [data-bz-node="hc-dt"]{margin-top:26px}
body [data-bz-node="hc-dt"] .bz-text{max-width:none}
body [data-bz-node="hc-dt"] p{font:700 10.5px/1.4 var(--font-body);letter-spacing:.24em;text-transform:uppercase;color:rgba(255,255,255,.72);margin:0}
body [data-bz-node="hc-dcta"]{margin-top:8px}
body [data-bz-node="hc-dcta"] .bz-btns{margin:0}
body [data-bz-node="hc-dcta"] .bz-btn{padding:0;border:0;background:none;border-radius:0;color:#fff;font:700 clamp(28px,3.1vw,40px)/1.1 var(--font-heading);letter-spacing:.01em;text-decoration:none;text-transform:none;min-height:0;height:auto}
body [data-bz-node="hc-dcta"] .bz-btn:hover{color:var(--accent)}
body [data-bz-node="hc-dtext"] .bz-text{max-width:none;margin-top:16px}
body [data-bz-node="hc-dtext"] p{font:400 13px/1.7 var(--font-body);color:rgba(255,255,255,.85);margin:0}

@media (max-width:1100px){
  body [data-bz-node="hc"]{padding:64px 24px}
  body [data-bz-node="hc-h"] h2{font-size:30px}
  body [data-bz-node="hc-grid"]{grid-template-columns:1fr}
}
@media (max-width:640px){
  body [data-bz-node="hc"]{padding:48px 20px}
  body [data-bz-node="hc-h"] h2{font-size:26px}
  body [data-bz-node="hc-grid"]{gap:16px;margin-top:28px}
  body [data-bz-node="hc-card"]{padding:26px 22px 14px}
  body [data-bz-node^="hc-day-"]{flex-direction:column;gap:4px;padding:13px 0}
  body [data-bz-node^="hc-dayname-"]{flex-basis:auto}
  body [data-bz-node="hc-dark"]{padding:30px 24px}
}
